import sys,heapq,math,numpy as np
sys.path.insert(0,'/app/output');import gen
from scipy import ndimage as ndi
m,s,d=gen.load_geometry();lab,n=ndi.label(m,np.ones((3,3)));pts,adj=gen.adjacency(s)

def paths_for(c,k):
 nodes=[i for i,p in enumerate(pts) if lab[p]==c]
 odd=set(i for i in nodes if len(adj[i])%2)
 paths={}
 for src in odd:
  dd={src:0};prev={};heap=[(0,src)]
  while heap:
   dist,v=heapq.heappop(heap)
   if dist!=dd[v]:continue
   for u in adj[v]:
    w=math.dist(pts[v],pts[u]);nd=dist+w
    if nd<dd.get(u,1e9):dd[u]=nd;prev[u]=v;heapq.heappush(heap,(nd,u))
  for dst in odd:
   if src<dst:
    path=[dst];v=dst
    while v!=src:v=prev[v];path.append(v)
    paths[src,dst]=(dd[dst],path[::-1])
 candidates=sorted((length,a,b,path) for (a,b),(length,path) in paths.items())
 selected=[];paired=set()
 for length,a,b,path in candidates:
  if len(odd)-len(paired)<=2*k:break
  if a not in paired and b not in paired:
   selected.append((length,a,b,path));paired.add(a);paired.add(b)
 print(c,'wanted',k,'odd',len(odd),'pairs',len(selected),'duplicate px',round(sum(x[0] for x in selected),1),'longest',sorted([round(x[0],1) for x in selected],reverse=True)[:6])
for c,k in [(1,1),(4,1),(5,5),(6,5),(7,4),(8,4),(9,1),(10,1)]:paths_for(c,k)
